const crypto = require('crypto');
// Signs a request to the Laravel automation API (docs/API_DOCUMENTATION.md section 7).
// Canonical string: timestamp, nonce, METHOD, path with query, workflow id, execution key, raw body.
const signRequest = (method, path, body, ctx) => {
  const base = String($env.EGS_API_BASE_URL || '').replace(/\/+$/, '');
  const secret = String($env.EGS_AUTOMATION_HMAC_SECRET || '');
  if (!base || !secret) {
    throw new Error('EGS_API_BASE_URL and EGS_AUTOMATION_HMAC_SECRET must be set in the n8n environment.');
  }
  const uri = '/api/v1/automation/' + String(path).replace(/^\/+/, '');
  const raw = body === null ? '' : JSON.stringify(body);
  const timestamp = String(Math.floor(Date.now() / 1000));
  const nonce = crypto.randomBytes(16).toString('hex');
  const canonical = [timestamp, nonce, method, uri, ctx.workflow_id, ctx.execution_key, raw].join('\n');
  const signature = crypto.createHmac('sha256', secret).update(canonical).digest('hex');
  return {
    method,
    url: base + uri,
    body: raw,
    headers: {
      'Accept': 'application/json',
      'X-Workflow-Id': ctx.workflow_id,
      'X-Execution-Key': ctx.execution_key,
      'X-Automation-Timestamp': timestamp,
      'X-Automation-Nonce': nonce,
      'X-Automation-Signature': signature,
    },
  };
};
const event = $input.first().json.event || {};
if (!event.event_id) {
  throw new Error('Called without an outbox event; this workflow is started by Z03.');
}
const executionKey = 'D05:' + event.event_id;
const ctx = { workflow_id: 'D05', execution_key: executionKey };
ctx.event_id = event.event_id;
return [{ json: { ctx, request: signRequest('POST', 'executions', { action: 'start' }, ctx) } }];

